INSERT INTO `riwayat_chat` (`id`, `user_id`, `id_sesi`, `id_rekomendasi`, `pertanyaan`, `jawaban`, `created_at`, `updated_at`) VALUES
(1, 3, '53686574-9e0e-4890-b826-b98dd5474718', 1, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Teknologi Informasi adalah pilihan terbaik. Dengan prestasi di bidang juara 2 olimpiade informatika, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(2, 3, '53686574-9e0e-4890-b826-b98dd5474718', 1, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai mtk, fisika, kimia, biologi Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(3, 4, '99f41a25-5daa-454e-9b6f-5885c93cf242', 2, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Teknik adalah pilihan terbaik. Dengan prestasi di bidang juara lomba robotika regional, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(4, 4, '99f41a25-5daa-454e-9b6f-5885c93cf242', 2, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai mtk, fisika, kimia, biologi Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(5, 5, 'b6c7ea5a-e835-4126-ac7a-4bc27637b760', 3, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Produksi Pertanian adalah pilihan terbaik. Dengan prestasi di bidang juara pameran tanaman hidroponik, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(6, 5, 'b6c7ea5a-e835-4126-ac7a-4bc27637b760', 3, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai mtk, fisika, kimia, biologi Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(7, 6, '5322a8f1-70d6-4630-bd63-ad405d33b1f6', 4, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Peternakan adalah pilihan terbaik. Dengan prestasi di bidang penulis jurnal ilmiah tingkat sekolah, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(8, 6, '5322a8f1-70d6-4630-bd63-ad405d33b1f6', 4, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai mtk, fisika, kimia, biologi Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(9, 7, '83a54747-4c2c-4a65-a78f-9671962a44fd', 5, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Manajemen Agribisnis adalah pilihan terbaik. Dengan prestasi di bidang juara kompetisi bisnis plan nasional, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(10, 7, '83a54747-4c2c-4a65-a78f-9671962a44fd', 5, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai ekonomi, geografi, sosiologi, sejarah Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(11, 8, '04fa19e6-b97a-415f-ab0f-c6ea19661dc9', 6, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Akuntansi adalah pilihan terbaik. Dengan prestasi di bidang finalis kompetisi akuntansi wilayah, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(12, 8, '04fa19e6-b97a-415f-ab0f-c6ea19661dc9', 6, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai ekonomi, mtk, sejarah, sosiologi Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(13, 9, '7c6ae641-8ec1-4b2d-8c68-ea93971005dd', 7, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Bahasa Komunikasi adalah pilihan terbaik. Dengan prestasi di bidang juara debat tingkat propinsi, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(14, 9, '7c6ae641-8ec1-4b2d-8c68-ea93971005dd', 7, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai sosiologi, sejarah, ekonomi, geografi Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(15, 10, 'b3595271-87e8-4310-a20b-0ea8a4d56f1b', 8, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Manajemen Agribisnis adalah pilihan terbaik. Dengan prestasi di bidang pengusaha kuliner muda, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(16, 10, 'b3595271-87e8-4310-a20b-0ea8a4d56f1b', 8, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai ekonomi, geografi, mtk, sosiologi Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(17, 11, 'a7e3bd9c-f82e-4d19-88a6-39054bb08b8c', 9, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Teknologi Informasi adalah pilihan terbaik. Dengan prestasi di bidang top 10 innovation challenge, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(18, 11, 'a7e3bd9c-f82e-4d19-88a6-39054bb08b8c', 9, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai mtk, fisika, kimia, biologi Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(19, 12, '945df9f6-f859-48db-ad72-beafef166a79', 10, 'Jurusan apa yang cocok untuk saya?', 'Berdasarkan nilai dan minat Anda, Teknik adalah pilihan terbaik. Dengan prestasi di bidang juara kompetisi energi terbarukan, Anda memiliki potensi besar untuk sukses.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(20, 12, '945df9f6-f859-48db-ad72-beafef166a79', 10, 'Mengapa jurusan tersebut cocok untuk saya?', 'Karena nilai fisika, mtk, kimia, biologi Anda menunjukkan keunggulan di area yang relevan dengan jurusan tersebut.', '2026-05-12 11:06:32', '2026-05-12 11:06:32'),
(21, 2, 'session_1', NULL, 'Jadi menurut sistem saya cocok ambil jurusan apa ya?', 'Berdasarkan hasil analisis, untuk profile Anda yang nilai MTK-Fisika bagus dan minat coding kuat, Teknik Informatika adalah pilihan yang selaras. Anda bisa fokus cybersecurity atau development.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(22, 2, 'session_1', NULL, 'Cybersecurity lebih amankan karir atau development?', 'Dua-duanya prospek bagus. Cybersecurity ada demand dari government dan finance yang stabil. Development skills lebih flexible bisa startup atau big tech. Lihat passion Anda lebih ke yang mana.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(23, 3, 'session_2', NULL, 'Saya pengen jurusan yang bisa langsung applicable untuk robotika', 'Untuk robotika, Teknik Elektro atau Teknik Mesin sangat applicable. Dengan score fisika 90 Anda, dua jurusan ini cocok. Teknik Elektro kalau fokus control system, Teknik Mesin kalau fokus mechanical design.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(24, 3, 'session_2', NULL, 'Lebih pilih mana sih?', 'Lihat passion Anda lebih ke elektrik atau mekanik? Kalau suka coding dan control systems, Teknik Elektro. Kalau suka design fisik dan assemble-dismantle, Teknik Mesin. Keduanya relevant untuk robotika.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(25, 4, 'session_3', NULL, 'Bisa lanjut kedokteran dari TPI nggak?', 'Untuk kedokteran, value akademik dan jalur masuk lebih strict dibanding TPI. Tapi calondidik bisa persiapan dari TPI, terutama biologi dan kimia. Fokus banget di olimpiade sains untuk booster nilai masuk.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(26, 4, 'session_3', NULL, 'TPI itu apa ya singkatannya?', 'Teknik Pertanian dan Industri di Polije. Tapi kalau target kedokteran, mungkin bisa cek juga program kesehatan dulu untuk experience, atau aplikasi kedokteran pure dari outcome awal.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(27, 5, 'session_4', NULL, 'Agribusiness itu nanti kerjanya kayak apa?', 'Bisa jadi manager farm, business development untuk agritech, supply chain untuk produk pertanian, atau entrepreneur. Banyak pilihan tergantung spesialisasi yang dipilih di kuliah.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(28, 5, 'session_4', NULL, 'Gaji fresh graduate agritech berapa kira-kira?', 'Startup agritech biasanya 4-6 juta tergantung posisi dan lokasi. Corporate agribusiness bisa 5-8 juta. Tapi kalau entrepreneurship sendiri, income tergantung success rate usaha Anda.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(29, 6, 'session_5', NULL, 'Polije punya program internship nggak?', 'Ada, biasanya di semester akhir. Untuk program Peternakan, ada partnership dengan farm modern dan feed company. Cek dengan prodi langsung untuk detail placement.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(30, 6, 'session_5', NULL, 'Boleh apply internship di abroad nggak?', 'Tergantung kebijakan prodi, tapi generally bisa diskusi dengan pembimbing. Ada beberapa students yang udah internship di Malaysia atau Thailand. Usahakan komunikasi dengan prodi sejak early semester.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(31, 7, 'session_6', NULL, 'Perlu les atau belajar sendiri sebelum masuk kuliah?', 'Tergantung kesiapan Anda. Kalau values academic udah solid, bisa self-study dengan referensi online. Tapi kalau mau jadi standout di semester pertama, bisa ambil kursus online tentang fondasi subject.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(32, 7, 'session_6', NULL, 'Ada rekomendasi website atau platform belajar nggak?', 'Udah banyak. Coursera, Udemy, Khan Academy bagus untuk foundational. Indonesia ada Ruangguru atau Zenius. Tapi yang paling penting engagement sama dosen dan teman-teman di kelas nanti.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(33, 8, 'session_7', NULL, 'Agak ragu antara Akuntansi sama Management', 'Dua jurusan ini beda fokus. Akuntansi lebih technical dan detail-oriented, Management lebih strategic dan leader-focused. Lihat strength Anda: detail dan angka atau big picture dan people? Itu bisa guide decision.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(34, 8, 'session_7', NULL, 'Kalau pilih Management, bisa dapat nilai invest yang bagus nggak dari sekolah?', 'Bisa. Dengan nilai ekonomi 90 Anda, management akan mudah. Cuma akuntansi mungkin lebih certified langsung (JATS). Management lebih butuh experience dan soft skill yang dibangun di luar kelas.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(35, 9, 'session_8', NULL, 'Ada beasiswa untuk jurusan sosial nggak?', 'Ada beberapa dari government dan foundation. Polije ada beasiswa akademik based on nilai. NGO juga sering sponsor untuk program kemanusiaan atau education. Tapi bisa juga dari corporate yang peduli CSR.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(36, 9, 'session_8', NULL, 'Requirement beasiswa biasanya apa?', 'Tergantung sumber. Academic scholarship butuh nilai bagus. Need-based butuh dokumentasi ekonomi. Full scholarship biasanya maintain GPA minimal 3.0 dan aktif di organisasi sosial.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(37, 10, 'session_9', NULL, 'Pariwisata di Indonesia prospeknya gimana pasca COVID?', 'Recovery udah bagus. Domestic tourism naik, international mulai balik. Tapi industry butuh profesional yang innovative, bukan hanya tour guide. Positioning diri Anda sebagai strategic player, bukan operational level.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(38, 10, 'session_9', NULL, 'Jadi hospitality manager itu punya team berapa biasanya?', 'Tergantung size hotel. Small hotel (50 kamar) mungkin 5-10 staff. Mid-range (100-200 kamar) 20-50 staff. Besar (300+ kamar) bisa 100+. Semakin besar, semakin kompleks management-nya.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(39, 11, 'session_10', NULL, 'Komunikasi itu subject berat nggak di kuliah?', 'Tidak terlalu berat seperti teknik atau science. Tapi demanding dalam hal project, presentasi, dan banyak reading. Kalau Anda suka talking dan creative, ini cocok. Tantangan lebih ke academic rigor, bukan mathematical complexity.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(40, 11, 'session_10', NULL, 'Ada lab atau praktik langsung nggak?', 'Ada. Biasanya ada lab communicative, media production, bahkan ada broadcast studio. Praktik langsung dengan project nyata untuk client atau media partner. Itu yang membuat komunikasi menarik.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(41, 2, 'session_11', NULL, 'Kenalin dong senior-senior di Teknik Informatika', 'Udah ada program mentoring di Polije. Senior bisa di-connect melalui alumni network atau student organization. Mereka helpful banget share experience dan tips lolos interview di tech company.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(42, 3, 'session_12', NULL, 'Lab di Teknik Elektro lengkap nggak untuk robotika?', 'Lumayan lengkap. Ada microcontroller lab, digital logic lab. Untuk advanced robotics, bisa kolaborasi dengan Teknik Mesin juga. Ada makerspace bersama yang membantu student projects.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(43, 4, 'session_13', NULL, 'Kesehatan di Polije fokus apa ya?', 'Ada program Ilmu Gizi, Teknologi Laboratorium Medis, dan Kesehatan Masyarakat. Fokus ke applied health, tidak pure medical science. Cocok untuk Anda yang peduli community health.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(44, 5, 'session_14', NULL, 'Mahasiswa agribusiness banyak nggak?', 'Cukup banyak, sekitar 100 per tahun. Intake lumayan tinggi karena demand industri. Networking sama peers bisa bagus untuk future business partnership.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(45, 6, 'session_15', NULL, 'Peternakan di Polije punya farm sendiri nggak?', 'Ada. Farm sendiri untuk praktik langsung sama students. Facilities bagus, ada kandang modern, equipment hewan medis. Bisa langsung hands-on dari semester pertama.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(46, 7, 'session_16', NULL, 'Manajemen jurusan itu terlalu general nggak?', 'Dalam kuliah ada specialization. Semester awal general foundation, nanti semester 5-6 bisa pilih tracks seperti operations, finance, marketing, atau digital business. Jadi nggak general-general amat.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(47, 8, 'session_17', NULL, 'Akuntansi itu paling banyak ngitung nggak si?', 'Lumayan. Tapi sekarang accounting lebih ke understanding system, analysis, dan business advisory. Ngitung masih ada tapi banyak software yang bantu. Focus lebih ke thinking skills.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(48, 9, 'session_18', NULL, 'Social welfare program itu study apa aja sih?', 'Social policy, community development methods, case management, research methods. Praktik langsung di komunitas juga. Banyak fieldwork yang meaningful.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(49, 10, 'session_19', NULL, 'Tourism management itu enaknya atau challenging?', 'Enaklah karena hands-on banyak, networking luas. Challenging dari fast-paced industry yang selalu berubah. Tapi kalau Anda adaptable dan social, ini worth it.', '2026-05-17 07:12:33', '2026-05-17 07:12:33'),
(50, 19, NULL, 57, 'Berapa lama program studi ini?', 'Terima kasih atas pertanyaannya. Berdasarkan profil akademik dan minat Anda, saya merekomendasikan jurusan yang sesuai dengan kemampuan dan tujuan karir Anda.', '2026-05-19 16:02:54', '2026-05-19 16:02:54'),
